void loadMqttSettings() {
  Serial.println("[DEBUG] loadMqttSettings() STARTED");

  EEPROM.begin(EEPROM_SIZE);

  // Сначала обнуляем буферы, чтобы не было мусора
  memset(eep_mqtt_server, 0, sizeof(eep_mqtt_server));
  memset(eep_mqtt_user, 0, sizeof(eep_mqtt_user));
  memset(eep_mqtt_pass, 0, sizeof(eep_mqtt_pass));

  // Теперь читаем в уже обнулённые буферы
  EEPROM.get(OFFSET_SERVER, eep_mqtt_server);
  EEPROM.get(OFFSET_USER, eep_mqtt_user);
  EEPROM.get(OFFSET_PASS, eep_mqtt_pass);
  EEPROM.end();

  // Принудительно ставим завершающий ноль на случай, если в EEPROM нет \0
  eep_mqtt_server[32] = '\0';
  eep_mqtt_user[32]   = '\0';
  eep_mqtt_pass[32]   = '\0';

  mqtt_server = String(eep_mqtt_server);
  mqtt_user   = String(eep_mqtt_user);
  mqtt_pass   = String(eep_mqtt_pass);

  Serial.print("[DEBUG] LOADED: Server='");
  Serial.print(mqtt_server);
  Serial.print("' (len=");
  Serial.print(mqtt_server.length());
  Serial.print("), User='");
  Serial.print(mqtt_user);
  Serial.print("' (len=");
  Serial.println(mqtt_user.length());
}

void saveMqttSettings() {
  // Обрезаем и сразу пишем в буферы
  mqtt_server.substring(0, 32).toCharArray(eep_mqtt_server, 33);
  mqtt_user.substring(0, 32).toCharArray(eep_mqtt_user, 33);
  mqtt_pass.substring(0, 32).toCharArray(eep_mqtt_pass, 33);

  // Важно: ставим завершающий ноль, если строка короче 32
  eep_mqtt_server[32] = '\0';
  eep_mqtt_user[32]   = '\0';
  eep_mqtt_pass[32]   = '\0';

  Serial.println("[MQTT] Saving to EEPROM at offsets: " + String(OFFSET_SERVER));
  Serial.println("[DEBUG] WRITING to EEPROM...");

  EEPROM.begin(EEPROM_SIZE);

  // Пишем именно из подготовленных буферов
  EEPROM.put(OFFSET_SERVER, eep_mqtt_server);
  EEPROM.put(OFFSET_USER, eep_mqtt_user);
  EEPROM.put(OFFSET_PASS, eep_mqtt_pass);

  EEPROM.commit();
  EEPROM.end();

  Serial.println("[MQTT] Настройки сохранены в EEPROM!");
}

