// Расчёт CRC16
uint16_t calculateCRC16(const uint8_t* data, size_t length) {
  uint16_t crc = 0xFFFF;
  for (size_t i = 0; i < length; i++) {
    crc ^= data[i];
    for (int j = 0; j < 8; j++) {
      if (crc & 0x0001) {
        crc = (crc >> 1) ^ 0xA001;
      } else {
        crc >>= 1;
      }
    }
  }
  return crc;
}

// Отправка команды Dooya
void sendDooyaCommand(uint8_t function, uint8_t data = 0) {
  uint8_t command[7];
  command[0] = 0x55;                         // стартовый код
  command[1] = (DEVICE_ADDRESS >> 8) & 0xFF; // старший байт адреса
  command[2] = DEVICE_ADDRESS & 0xFF;        // младший байт адреса
  command[3] = function;                     // функция
  command[4] = data;                         // данные (для процентов 0–100)

  // Расчёт CRC16
  uint16_t crc = calculateCRC16(command, 5);
  command[5] = (crc >> 8) & 0xFF; // старший байт CRC
  command[6] = crc & 0xFF;        // младший байт CRC

  dooyaSerial.write(command, 7);
  dooyaSerial.flush();
}

// Обработка входящих данных от Dooya
void handleDooyaResponse() {
  while (dooyaSerial.available()) {
    uint8_t byte = dooyaSerial.read();
    buffer[bufferIndex++] = byte;

    // Проверка на полный пакет (7 байт)
    if (bufferIndex >= 7 && buffer[0] == 0x55) {
      // Проверка CRC
      uint16_t receivedCRC = (buffer[5] << 8) | buffer[6];
      uint16_t calculatedCRC = calculateCRC16(buffer, 5);

      if (receivedCRC == calculatedCRC) {
        // Пакет корректен
        uint8_t function = buffer[3];
        uint8_t data = buffer[4];

        // Публикация статуса в MQTT
        String topic = "dooya/status";
        String payload = "function:" + String(function) + ",data:" + String(data);
        client.publish(topic.c_str(), payload.c_str());
      }
      bufferIndex = 0; // сброс буфера
    }
  }
}

// Обработчик MQTT‑сообщений
void mqttCallback(char* topic, byte* payload, unsigned int length) {
  String message = "";
  for (int i = 0; i < length; i++) {
    message += (char)payload[i];
  }

  if (String(topic) == "dooya/command") {
    if (message == "open") {
      sendDooyaCommand(DOOYA_OPEN);
    } else if (message == "close") {
      sendDooyaCommand(DOOYA_CLOSE);
    } else if (message == "stop") {
      sendDooyaCommand(DOOYA_STOP);
    } else if (message.startsWith("percent:")) {
      int percent = message.substring(8).toInt();
      if (percent >= 0 && percent <= 100) {
        sendDooyaCommand(DOOYA_PERCENT, percent);
      }
    }
  }
}

// Функция поиска адреса устройства Dooya
DooyaDevice findDooyaAddress() {
  DooyaDevice device;
  device.found = false;
  device.address = 0x0000;

  Serial.println("Начало поиска адреса устройства Dooya...");

  // Перебираем возможные адреса (можно ограничить диапазон для ускорения)
  for (uint16_t addr = 0x0001; addr <= 0xFFFF; addr++) {
    // Отправляем команду «стоп» с текущим адресом
    uint8_t command[7];
    command[0] = 0x55;               // стартовый код
    command[1] = (addr >> 8) & 0xFF; // старший байт адреса
    command[2] = addr & 0xFF;        // младший байт адреса
    command[3] = DOOYA_STOP;         // функция «стоп»
    command[4] = 0x00;               // данные не нужны

    // Расчёт CRC16
    uint16_t crc = calculateCRC16(command, 5);
    command[5] = (crc >> 8) & 0xFF; // старший байт CRC
    command[6] = crc & 0xFF;        // младший байт CRC

    // Отправка команды
    dooyaSerial.write(command, 7);
    dooyaSerial.flush();

    // Ждём ответа (таймаут 500 мс)
    unsigned long startTime = millis();
    while (millis() - startTime < 500) {
      if (dooyaSerial.available() >= 7) {
        uint8_t response[7];
        for (int i = 0; i < 7; i++) {
          response[i] = dooyaSerial.read();
        }

        // Проверяем стартовый байт и CRC
        if (response[0] == 0x55) {
          uint16_t receivedCRC = (response[5] << 8) | response[6];
          uint16_t calculatedCRC = calculateCRC16(response, 5);

          if (receivedCRC == calculatedCRC) {
            // Адрес найден!
            device.found = true;
            device.address = (response[1] << 8) | response[2];
            Serial.print("Адрес устройства найден: 0x");
            Serial.println(device.address, HEX);
            return device;
          }
        }
      }
    }

    // Небольшая задержка между попытками
    delay(10);
  }

  Serial.println("Адрес устройства не найден!");
  return device;
}

