// Обработчики веб‑сервера
void handleRoot() {
  String page = mainPage;
  page.replace("%IP_ADDRESS%", WiFi.localIP().toString());
  page.replace("%DEVICE_ADDR%", "0x" + String(DEVICE_ADDRESS, HEX));
  server.send(200, "text/html; charset=utf-8", page);
}

void handleCommand() {
  String action = server.arg("action");
  String valueStr = server.arg("value");

  if (action == "open") {
    sendDooyaCommand(DOOYA_OPEN);
    server.send(200, "text/plain", "Команда: Открыть");
  } else if (action == "close") {
    sendDooyaCommand(DOOYA_CLOSE);
    server.send(200, "text/plain", "Команда: Закрыть");
  } else if (action == "stop") {
    sendDooyaCommand(DOOYA_STOP);
    server.send(200, "text/plain", "Команда: Стоп");
  } else if (action == "percent" && valueStr != "") {
    int percent = valueStr.toInt();
    if (percent >= 0 && percent <= 100) {
      sendDooyaCommand(DOOYA_PERCENT, percent);
      server.send(200, "text/plain", "Команда: Процент " + String(percent));
    } else {
      server.send(400, "text/plain", "Ошибка: неверный процент");
    }
  } else {
    server.send(400, "text/plain", "Неизвестная команда");
  }
}

void handleStatus() {
  // Здесь можно реализовать получение реального статуса от устройства
  // Пока возвращаем статический статус
  static unsigned long lastStatusUpdate = 0;
  static String currentStatus = "Готов";

  if (millis() - lastStatusUpdate > 5000) {
