//Функция сохранения найденного адреса
void handleSaveAddress() {
  if (server.hasArg("addr")) {
    uint32_t addr = strtoul(server.arg("addr").c_str(), nullptr, 16);
    DEVICE_ADDRESS = (uint16_t)addr;

    // Сохраняем в своё место, не пересекаясь с MQTT
    EEPROM.begin(EEPROM_SIZE);
    EEPROM.put(OFFSET_DEVICE_ADDR, DEVICE_ADDRESS);
    EEPROM.commit();
    EEPROM.end();

    server.send(200, "text/html; charset=utf-8",
      "<h1>Адрес сохранён!</h1>"
      "<p>Новый адрес: 0x" + String(DEVICE_ADDRESS, HEX) + "</p>"
      "<p><a href='/'>Вернуться на главную</a></p>");
    delay(2000);
    ESP.restart();
  } else {
    server.send(400, "text/plain", "Ошибка: адрес не указан");
  }
}

