  if (addrFromEEPROM == 0 || addrFromEEPROM == 0xFFFF) {
    DEVICE_ADDRESS = 0x1234;
  } else {
    DEVICE_ADDRESS = addrFromEEPROM;
  }

  Serial.print("Используемый адрес устройства: 0x");
  Serial.println(DEVICE_ADDRESS, HEX);

  // Инициализация WiFiManager
  wifiManager.setAPCallback([](WiFiManager *myWiFiManager) {
    Serial.println("\nТочка доступа запущена. Подключитесь к: ESP8266_Dooya Пароль: dooya123");
