  });

  // Попытка подключения с сохранением настроек
  if (!WiFi.isConnected()) {
    if (!wifiManager.autoConnect("ESP8266_Dooya", "dooya123")) {
      Serial.println("Не удалось подключиться к Wi‑Fi, перезагрузка...");
      delay(3000);
      ESP.restart();
    }
  }

  Serial.println("\nПодключено к Wi‑Fi!");
  Serial.print("IP-адрес: ");
  Serial.println(WiFi.localIP());

  // Настройка веб‑сервера
  server.on("/", handleRoot);
  server.on("/command", handleCommand);
  server.on("/status", handleStatus);
  server.on("/find_address", handleFindAddress);
  server.on("/save_address", handleSaveAddress);
  server.on("/mqtt_setup", handleMqtSetup);

  server.on("/save_mqtt", HTTP_POST, []() {
    // Читаем и очищаем аргументы
    if (server.hasArg("mqtt_broker")) {
      String val = server.arg("mqtt_broker");
      val.trim();
      mqtt_server = val;
    }
    if (server.hasArg("mqtt_port")) {
      String val = server.arg("mqtt_port");
      val.trim();
      mqtt_port = val.toInt();
    }
    if (server.hasArg("mqtt_user")) {
      String val = server.arg("mqtt_user");
      val.trim();
      mqtt_user = val;
    }
    if (server.hasArg("mqtt_pass")) {
      String val = server.arg("mqtt_pass");
      val.trim();
      mqtt_pass = val;
    }

    saveMqttSettings();  

    server.send(200, "text/html; charset=utf-8",
      "<h1>Настройки сохранены!</h1>"
      "<p>Перезагрузка через 2 секунды...</p>"
      "<p><a href='/'>Назад</a></p>");
    delay(2000);
    ESP.restart();
  });

  server.begin();

  // Настройка MQTT
  Serial.print("MQTT Broker: "); Serial.println(mqtt_server);
  Serial.print("MQTT Port: "); Serial.println(mqtt_port);
  client.setServer(mqtt_server.c_str(), mqtt_port);
  client.setCallback(mqttCallback);
}


void loop() {
  // Обработка веб‑сервера
  server.handleClient();

  // Поддержание соединения MQTT
  if (!client.connected()) {
    reconnectMQTT();
  }
  client.loop();

  // Обработка ответов от Dooya
  handleDooyaResponse();
}

// Функция переподключения к MQTT
void reconnectMQTT() {
  if (client.connected()) return;

  // Если брокер не задан — не пытаемся подключаться
  if (mqtt_server.isEmpty()) {
    Serial.println("[MQTT] Брокер не задан. Пропускаем подключение.");
    delay(1000);
    return;
  }

  unsigned long startTime = millis();
  const unsigned long timeout = 8000;  // 8 секунд на одну попытку

  // Генерируем уникальное имя на основе MAC-адреса
  String clientId = "Dooya_" + String(WiFi.macAddress()).substring(6);

  Serial.print("Подключение к MQTT: ");
  Serial.print(mqtt_server);
  Serial.print(":");
  Serial.println(mqtt_port);

  // Цикл до успешного подключения
   while (!client.connected() && (millis() - startTime < timeout)) {
    Serial.print("Попытка подключения к MQTT... ");
    if (client.connect(clientId.c_str(), mqtt_user.c_str(), mqtt_pass.c_str())) {
      Serial.println("Успех!");
      client.subscribe("dooya/command");
      return;
    } else {
      int rc = client.state();
      Serial.print("Ошибка, rc=");
      Serial.println(rc);
      delay(2000);
    }
  }

  Serial.println("Не удалось подключиться к MQTT за отведённое время. Продолжаем работу без MQTT.");
}
